from z3 import *
s = Solver()
table = Array('table', IntSort(), IntSort())
for i in range(7):
    for j in range(7):
        s.add(table[i*7 + j] >= 0)
        s.add(table[i*7 + j] <= 6)
for i in range(7):
    s.add(table[i*7 + i] == i)
for i in range(7):
    row = [table[i*7 + j] for j in range(7)]
    s.add(Distinct(row))
for j in range(7):
    col = [table[i*7 + j] for i in range(7)]
    s.add(Distinct(col))
for i in range(7):
    for j in range(7):
        idx1 = table[i*7 + j]
        idx2 = table[j*7 + i]
        s.add(table[idx1 * 7 + idx2] == i)
print(s.check())
if s.check() == sat:
    m = s.model()
    sol = []
    for i in range(7):
        for j in range(7):
            val = m.eval(table[i*7 + j])
            sol.append(int(str(val)))
    print(sol)

